1	export function resolveReportWindow(now, window = 'current') {
2	  const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
3	  const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 1));
4	  if (window === 'previous') {
5	    return { start: new Date(now.getTime() - 30 * 86400000), end: now };
6	  }
7	  return { start, end };
8	}
