test('current uses the full UTC calendar month', () => {
  const actual = resolveReportWindow(new Date('2026-03-15T12:00:00Z'));
  assert.equal(actual.start.toISOString(), '2026-03-01T00:00:00.000Z');
  assert.equal(actual.end.toISOString(), '2026-04-01T00:00:00.000Z');
});

test('previous uses the immediately preceding full UTC calendar month', () => {
  const actual = resolveReportWindow(new Date('2026-03-15T12:00:00Z'), 'previous');
  assert.equal(actual.start.toISOString(), '2026-02-01T00:00:00.000Z');
  assert.equal(actual.end.toISOString(), '2026-03-01T00:00:00.000Z');
});

test('previous crosses a year boundary when now is in January', () => {
  const actual = resolveReportWindow(new Date('2026-01-15T12:00:00Z'), 'previous');
  assert.equal(actual.start.toISOString(), '2025-12-01T00:00:00.000Z');
  assert.equal(actual.end.toISOString(), '2026-01-01T00:00:00.000Z');
});
